struct Cam{
    vec3 pos;
    vec3 dir;
    vec3 right;
    vec3 up;
}cam;



void mainImage( out vec4 O, in vec2 C )
{
    vec2 uv =(C - 0.5 * iResolution.xy)/iResolution.y;

   // vec3 ray;
   // ray.xy =uv;
   // ray.z = 1.0;

    vec4 sphere = vec4(0.0,0.0,2.0,1.0);
    //vec3 o = vec3(0.0) - sphere.xyz;


    //插入这段抽象摄像的代码
    float t =iTime;
    cam.pos = sphere.xyz + vec3(sin(t),0.0,cos(t)) * 3.0;
    cam.dir = normalize(sphere.xyz - cam.pos);
    cam.right = -cross(cam.dir , vec3(.0,1.0,.0));
    cam.up = -cross(cam.right,cam.dir);



    vec3 ray = normalize(uv.x * cam.right + uv.y * cam.up + 1.0 * cam.dir);
    vec3 o = cam.pos - sphere.xyz;



    //根据圆的公式和射线的公式，求交
    float a = dot(ray,ray);
    float b = 2.0 * dot(o,ray);
    float c = dot(o,o) - sphere.w *sphere.w;
    float delta =  b * b -4.0*a*c;

    float k;

    O = vec4(0.0);

    if(delta<0.0){ //剔除无解
        O = texture(iChannel0,ray);
        return;
    }
    //我们只需求k小（在前面的）的那个交点
    k = (-b - sqrt(delta))/(2.0 * a);

    vec3 p = cam.pos + k * ray;




    //求法向并归一化，增加光照
    vec3 normal = (p - sphere.xyz)/sphere.w;
    vec3 dirLight = normalize(vec3(-1,-1,0.2));

    vec3 diffuse = vec3(1.0) * pow(max(0.0,(dot(normal,-dirLight)+10.0)/11.0),12.0);
    vec3 ambient = vec3(0.8,0.7,0.7) *.12;

    O.xyz = min(diffuse + ambient,1.0);
}
